-- Read-only catalog inspection. Called only by run.py on its own socket.
WITH RECURSIVE
scope(name) AS (VALUES ('guides'),('reviews'),('guide_claims'),('claim_evidence'),('guide_details'),('guide_media'),('moderation_audit')),
rels AS (SELECT c.oid,c.relname,c.relowner,c.relrowsecurity,c.relforcerowsecurity,c.relacl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN scope s ON s.name=c.relname WHERE n.nspname='public' AND c.relkind IN ('r','p')),
roles AS (SELECT oid,rolname,rolsuper,rolbypassrls,rolinherit,rolcanlogin FROM pg_roles WHERE left(rolname,3)<>'pg_'),
funcs AS (SELECT p.oid,p.proname,p.proowner,p.prosecdef,p.proconfig,p.proacl FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('admin_decide_review','admin_decide_claim','is_site_admin','refresh_guide_rating','reviews_rating_trigger','throttle_review_submission')),
paths(app,at,path,edges) AS (
 SELECT r.oid,r.oid,ARRAY[r.rolname]::text[],ARRAY[]::jsonb[] FROM roles r WHERE r.rolname IN ('anon','authenticated')
 UNION ALL
 SELECT paths.app,m.roleid,paths.path||parent.rolname,paths.edges||jsonb_build_object('member',child.rolname,'role',parent.rolname,'inherit_option',to_jsonb(m)->'inherit_option','set_option',to_jsonb(m)->'set_option','admin_option',m.admin_option,'member_rolinherit',child.rolinherit)
 FROM paths JOIN pg_auth_members m ON m.member=paths.at JOIN pg_roles child ON child.oid=m.member JOIN pg_roles parent ON parent.oid=m.roleid WHERE NOT parent.rolname=ANY(paths.path)
),
member_paths(group_oid,member_oid,path) AS (
 SELECT m.roleid,m.member,ARRAY[pr.rolname,mr.rolname]::text[] FROM pg_auth_members m JOIN pg_roles pr ON pr.oid=m.roleid JOIN pg_roles mr ON mr.oid=m.member
 UNION ALL
 SELECT mp.group_oid,m.member,mp.path||r.rolname FROM member_paths mp JOIN pg_auth_members m ON m.roleid=mp.member_oid JOIN pg_roles r ON r.oid=m.member WHERE NOT r.rolname=ANY(mp.path)
)
SELECT jsonb_build_object(
 'postgres_version',current_setting('server_version'),
 'server_version_num',current_setting('server_version_num')::int,
 'scope_expected_tables',(SELECT jsonb_agg(name ORDER BY name) FROM scope),
 'relations',(SELECT jsonb_agg(jsonb_build_object('name',relname,'owner',pg_get_userbyid(relowner),'rls_enabled',relrowsecurity,'rls_forced',relforcerowsecurity) ORDER BY relname) FROM rels),
 'policies',(SELECT jsonb_agg(jsonb_build_object('table',tablename,'name',policyname,'roles',roles,'command',cmd,'permissive',permissive,'using',qual,'check',with_check) ORDER BY tablename,policyname) FROM pg_policies WHERE schemaname='public' AND tablename IN (SELECT name FROM scope)),
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypass_rls',rolbypassrls,'role_inherit',rolinherit,'login',rolcanlogin,'classification',CASE WHEN rolname IN ('anon','authenticated') THEN 'application' WHEN rolname IN ('service_role','qa_owner') THEN 'trusted_fixture_only' WHEN rolsuper OR rolbypassrls THEN 'privileged_or_bypass' ELSE 'synthetic_group_or_member' END) ORDER BY rolname) FROM roles),
 'membership_paths',(SELECT coalesce(jsonb_agg(jsonb_build_object('application_role',app_role.rolname,'path',paths.path,'edges',paths.edges,'effective_usage',pg_has_role(paths.app,paths.at,'USAGE'),'membership',pg_has_role(paths.app,paths.at,'MEMBER')) ORDER BY app_role.rolname,paths.path),'[]'::jsonb) FROM paths JOIN pg_roles app_role ON app_role.oid=paths.app WHERE cardinality(paths.path)>1),
 'role_members',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee_role',g.rolname,'member',m.rolname,'path',mp.path,'effective_usage',pg_has_role(mp.member_oid,mp.group_oid,'USAGE')) ORDER BY g.rolname,mp.path),'[]'::jsonb) FROM member_paths mp JOIN pg_roles g ON g.oid=mp.group_oid JOIN pg_roles m ON m.oid=mp.member_oid),
 'table_effective',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'table',t.relname,'privilege',op,'acl_allowed',has_table_privilege(r.oid,t.oid,op)) ORDER BY r.rolname,t.relname,op) FROM roles r CROSS JOIN rels t CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) op),
 'column_effective',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'table',t.relname,'column',a.attname,'privilege',op,'acl_allowed',has_column_privilege(r.oid,t.oid,a.attnum,op)) ORDER BY r.rolname,t.relname,a.attnum,op) FROM roles r CROSS JOIN rels t JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','REFERENCES']) op WHERE r.rolname IN ('anon','authenticated')),
 'table_acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',t.relname,'grantee',coalesce(g.rolname,'PUBLIC'),'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY t.relname,coalesce(g.rolname,'PUBLIC'),x.privilege_type),'[]'::jsonb) FROM rels t CROSS JOIN LATERAL aclexplode(coalesce(t.relacl,acldefault('r',t.relowner))) x LEFT JOIN pg_roles g ON g.oid=x.grantee),
 'column_acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',t.relname,'column',a.attname,'grantee',coalesce(g.rolname,'PUBLIC'),'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY t.relname,a.attnum,coalesce(g.rolname,'PUBLIC'),x.privilege_type),'[]'::jsonb) FROM rels t JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped CROSS JOIN LATERAL aclexplode(a.attacl) x LEFT JOIN pg_roles g ON g.oid=x.grantee),
 'functions',(SELECT jsonb_agg(jsonb_build_object('signature',format('%I.%I(%s)',n.nspname,f.proname,pg_get_function_identity_arguments(f.oid)),'owner',pg_get_userbyid(f.proowner),'security_definer',f.prosecdef,'configuration',f.proconfig,'search_path',(SELECT v FROM unnest(f.proconfig) v WHERE v LIKE 'search_path=%' LIMIT 1),'definition',pg_get_functiondef(f.oid),'logic_status','definition_only_not_evaluated','effective',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'execute',has_function_privilege(r.oid,f.oid,'EXECUTE')) ORDER BY r.rolname) FROM roles r),'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',coalesce(g.rolname,'PUBLIC'),'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY coalesce(g.rolname,'PUBLIC'),x.privilege_type) FROM aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) x LEFT JOIN pg_roles g ON g.oid=x.grantee)) ORDER BY f.proname,pg_get_function_identity_arguments(f.oid)) FROM funcs f JOIN pg_namespace n ON n.oid=(SELECT pronamespace FROM pg_proc WHERE oid=f.oid)),
 'coverage',jsonb_build_object('schema','selected public reconstruction; guide_media synthetic','full_function_inventory','unknown','system_role_effective_matrix','uninspected','storage_definitions','uninspected','hosted_auth_jwt','uninspected','hosted_data_api','uninspected','hosted_role_memberships','uninspected','operation_authorization','not_proved_by_acl_or_policy_metadata')
) AS report;
